const USER_AGENT = "net.umanle.arca.android.playstore/0.9.75";
const TARGETS = [
  ["all", "전체"],
  ["title_content", "제목/내용"],
  ["title", "제목"],
  ["content", "내용"],
  ["nickname", "글쓴이"]
];

const select = (e, t, r) => ({
  type_name: "SelectFilter",
  type: e,
  name: t,
  state: 0,
  values: r.map(([e, t]) => ({ type_name: "SelectOption", name: t, value: e }))
});

const chosen = (e, t) => {
  const r = (e || []).find((e) => e.type === t);
  return r ? r.values[r.state].value : "";
};

const https = (e) => String(e || "").replace(/^\/\//, "https://");

class DefaultExtension extends MProvider {
  get supportsLatest() {
    return true;
  }

  pref(e) {
    try {
      const val = (new SharedPreferences).get(e);
      return val !== null && val !== undefined ? String(val).trim() : "";
    } catch (e) {
      return "";
    }
  }

  get params() {
    let addParams = {};
    
    // 1. additionalParams 파싱 시도
    try {
      const raw = this.source?.additionalParams;
      if (typeof raw === "string" && raw.trim() !== "") {
        addParams = JSON.parse(raw);
      } else if (typeof raw === "object" && raw !== null) {
        addParams = raw;
      }
    } catch (e) {}

    // 2. 파싱 실패 시 기본값 안전장치
    if (!addParams.board) {
      addParams = {
        board: "lovelove",
        category: "(건전-시리즈)",
        popularCategory: "(건전)"
      };
    }

    const prefBoard = this.pref("board");
    const prefCat = this.pref("category");
    const prefPopCat = this.pref("popularCategory");

    const board = prefBoard !== "" ? prefBoard : (addParams.board || "lovelove");
    const category = prefCat !== "" ? prefCat : (addParams.category || "");
    const popularCategory = prefPopCat !== "" ? prefPopCat : (addParams.popularCategory || category);

    return { board, category, popularCategory };
  }

  get board() {
    const { board: e } = this.params;
    if (!e || !/^[A-Za-z0-9_-]+$/.test(e)) {
      throw new Error("올바른 아카라이브 채널 ID가 아닙니다.");
    }
    return e;
  }

  getSourcePreferences() {
    return [
      {
        key: "board",
        editTextPreference: {
          title: "채널 ID",
          summary: "주소의 /b/<ID> 부분",
          value: "",
          dialogTitle: "채널 ID",
          dialogMessage: "예: lovelove",
        },
      },
      {
        key: "category",
        editTextPreference: {
          title: "최신 탭 카테고리",
          summary: "최신 목록에 표시할 category 값",
          value: "",
          dialogTitle: "최신 탭 카테고리",
          dialogMessage: "예: (건전-시리즈)",
        },
      },
      {
        key: "popularCategory",
        editTextPreference: {
          title: "인기 탭 카테고리",
          summary: "인기 목록에 표시할 category 값",
          value: "",
          dialogTitle: "인기 탭 카테고리",
          dialogMessage: "예: (건전)",
        },
      },
    ];
  }

  getHeaders() {
    return {
      "User-Agent": USER_AGENT,
      "X-Device-Token": this._token || (this._token = Array.from({ length: 64 }, () => Math.floor(16 * Math.random()).toString(16)).join(""))
    };
  }

  post(e) {
    const t = /^(?:https:\/\/arca\.live)?\/b\/([A-Za-z0-9_-]+)\/(\d+)(?:[?#]|$)/.exec(String(e));
    if (!t) throw new Error("아카라이브 게시글 주소가 아닙니다.");
    return { board: t[1], id: t[2] };
  }

  async api(e) {
    const t = this._client || (this._client = new Client({ timeout: 20, connectTimeout: 8 })),
      r = await t.get(`${this.source.baseUrl}/api/app${e}`, this.getHeaders());
    if (/<title>\s*Just a moment|id=["']cf-chl/i.test(r.body))
      throw new Error("WebView에서 사이트 인증을 완료한 후 다시 시도해 주세요.");
    let a;
    try {
      a = JSON.parse(r.body);
    } catch (e) {
      throw new Error(`아카라이브 응답을 읽을 수 없습니다 (HTTP ${r.statusCode}).`);
    }
    if (200 !== r.statusCode || !1 === a.result)
      throw new Error(`아카라이브: ${a.message || `HTTP ${r.statusCode}`}`);
    return a;
  }

  async list(e, { best: t = !1, query: r = "", target: a = "all" } = {}, targetCategory = "") {
    if (!Number.isSafeInteger(e) || e < 1) throw new Error("올바른 페이지 번호가 아닙니다.");
    const s = this.board,
      i = targetCategory !== "" ? targetCategory : this.params.category,
      n = [`p=${e}`];
    i && n.push(`category=${encodeURIComponent(i)}`),
      t && n.push("mode=best"),
      r.trim() && n.push(`target=${encodeURIComponent(a)}`, `keyword=${encodeURIComponent(r.trim().slice(0, 128))}`);
    const { articles: o = [], next: l } = await this.api(`/list/channel/${s}?${n.join("&")}`),
      c = o.filter((e) => e.id && e.title).map((e) => ({
        name: String(e.title).trim(),
        link: `/b/${s}/${e.id}`,
        imageUrl: https(e.thumbnailUrl)
      }));
    return { list: c, hasNextPage: c.length > 0 && Boolean(l) };
  }

  getPopular(e) {
    // 인기 탭에서는 popularCategory 사용
    return this.list(e, { best: !0 }, this.params.popularCategory);
  }

  getLatestUpdates(e) {
    // 최신 탭에서는 category 사용
    return this.list(e, { best: !1 }, this.params.category);
  }

  search(e, t, r) {
    return this.list(t, {
      best: "best" === chosen(r, "mode"),
      query: String(e || ""),
      target: chosen(r, "target") || "all"
    }, this.params.category);
  }

  getFilterList() {
    return [select("mode", "목록", [["", "최신"], ["best", "개념글"]]), select("target", "검색 대상", TARGETS)];
  }

  async article(e) {
    const { board: t, id: r } = this.post(e),
      a = await this.api(`/view/article/${t}/${r}`);
    return {
      data: a,
      link: `/b/${t}/${r}`,
      images: [...new Set((a.images || []).map(https).filter((e) => /^https:\/\/[^\s"'<>\\]+$/.test(e)))]
    };
  }

  async getDetail(e) {
    const { data: t, link: r, images: a } = await this.article(e),
      s = String(t.title || "").trim();
    if (!s) throw new Error("게시글을 찾을 수 없습니다. 삭제 또는 접근 제한 여부를 확인해 주세요.");
    const i = Date.parse(t.createdAt || "");
    return {
      name: s,
      link: r,
      imageUrl: a[0] || "",
      status: 1,
      author: String(t.nickname || "").trim(),
      genre: t.categoryDisplayName ? [String(t.categoryDisplayName)] : [],
      description: String(t.content || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim().slice(0, 500),
      chapters: [{ name: "본문", url: r, dateUpload: Number.isFinite(i) ? String(i) : null }]
    };
  }

  async getPageList(e) {
    const { images: t } = await this.article(e);
    if (!t.length) throw new Error("게시글 본문에 표시할 이미지가 없습니다.");
    return t.map((e) => ({ url: e, headers: { "User-Agent": USER_AGENT } }));
  }
}
